create extension if not exists pgcrypto;
create table if not exists categories(id bigint primary key generated always as identity,name text not null unique,slug text not null unique,created_at timestamptz default now());
create table if not exists products(id bigint primary key generated always as identity,name text not null,description text,price numeric(10,2) not null check(price>=0),sale_price numeric(10,2) check(sale_price is null or sale_price>=0),sku text unique not null,category_id bigint references categories(id),customizable boolean default false,material text default 'Premium Cotton',care_instructions text,status text default 'active' check(status in('active','draft','archived')),low_stock_threshold int default 10,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists product_variants(id bigint primary key generated always as identity,product_id bigint not null references products(id) on delete cascade,size text not null,color text default 'Black',created_at timestamptz default now(),unique(product_id,size,color));
create table if not exists product_images(id bigint primary key generated always as identity,product_id bigint not null references products(id) on delete cascade,image_url text not null,alt_text text,display_order int default 0,created_at timestamptz default now());
create table if not exists inventory(id bigint primary key generated always as identity,product_id bigint not null references products(id) on delete cascade,variant_id bigint references product_variants(id) on delete cascade,stock_quantity int not null default 0 check(stock_quantity>=0),reserved_stock int not null default 0 check(reserved_stock>=0),created_at timestamptz default now(),updated_at timestamptz default now(),unique(product_id,variant_id));
create table if not exists user_profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text unique,phone text,is_admin boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists customer_addresses(id bigint primary key generated always as identity,user_id uuid not null references auth.users(id) on delete cascade,label text,full_name text,phone text,address text,city text,wilaya text,notes text,created_at timestamptz default now());
create table if not exists carts(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,session_id text unique,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists cart_items(id bigint primary key generated always as identity,cart_id uuid not null references carts(id) on delete cascade,product_id bigint not null references products(id),variant_id bigint references product_variants(id),quantity int not null check(quantity>0),personalization jsonb,created_at timestamptz default now(),unique(cart_id,product_id,variant_id));
create table if not exists orders(id bigint primary key generated always as identity,order_number text unique not null,user_id uuid references auth.users(id),customer_name text not null,customer_email text not null,customer_phone text not null,shipping_address text not null,shipping_city text not null,shipping_wilaya text not null,delivery_notes text,subtotal numeric(10,2) not null,shipping_cost numeric(10,2) default 0,total numeric(10,2) not null,payment_status text default 'pending',fulfillment_status text default 'new',internal_notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists order_items(id bigint primary key generated always as identity,order_id bigint not null references orders(id) on delete cascade,product_id bigint not null references products(id),variant_id bigint references product_variants(id),quantity int not null check(quantity>0),unit_price numeric(10,2) not null,personalization jsonb,created_at timestamptz default now());
create table if not exists uploaded_assets(id bigint primary key generated always as identity,user_id uuid references auth.users(id) on delete set null,storage_path text not null,original_name text,content_type text,size_bytes int,created_at timestamptz default now());
create table if not exists personalizations(id bigint primary key generated always as identity,order_item_id bigint references order_items(id) on delete cascade,customer_id uuid references auth.users(id),text_content text,font_family text,text_size int,position text,rotation int default 0,scale numeric(3,2) default 1,placement text default 'front',artwork_url text,artwork_file_size int,status text default 'pending',admin_notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists order_status_history(id bigint primary key generated always as identity,order_id bigint not null references orders(id) on delete cascade,status text not null,note text,created_at timestamptz default now());
create table if not exists store_settings(id int primary key default 1,brand_name text default 'JUST PRINT',shipping_flat numeric(10,2) default 600,free_shipping_threshold numeric(10,2) default 10000,updated_at timestamptz default now());
create index if not exists products_status_idx on products(status);create index if not exists orders_created_idx on orders(created_at desc);create index if not exists inventory_product_idx on inventory(product_id);create index if not exists history_order_idx on order_status_history(order_id,created_at);
create or replace function is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from user_profiles where id=auth.uid() and is_admin=true)$$;
create or replace function place_order(p_customer jsonb,p_items jsonb,p_user uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare v_order_id bigint;v_num text;v_sub numeric:=0;v_ship numeric:=600;v_item jsonb;v_p products%rowtype;v_q int;v_price numeric;v_inv inventory%rowtype;begin if jsonb_array_length(p_items)=0 then raise exception 'Cart is empty';end if;v_num='JP-'||upper(substr(encode(gen_random_bytes(5),'hex'),1,8));insert into orders(order_number,user_id,customer_name,customer_email,customer_phone,shipping_address,shipping_city,shipping_wilaya,delivery_notes,subtotal,shipping_cost,total) values(v_num,p_user,p_customer->>'name',p_customer->>'email',p_customer->>'phone',p_customer->>'address',p_customer->>'city',p_customer->>'wilaya',p_customer->>'notes',0,v_ship,0) returning id into v_order_id;for v_item in select * from jsonb_array_elements(p_items) loop v_q=greatest(1,least(20,(v_item->>'quantity')::int));select * into v_p from products where id=(v_item->>'product_id')::bigint and status='active' for update;if not found then raise exception 'Product unavailable';end if;v_price=coalesce(v_p.sale_price,v_p.price);select * into v_inv from inventory where product_id=v_p.id and (variant_id=(nullif(v_item->>'variant_id',''))::bigint or (variant_id is null and nullif(v_item->>'variant_id','') is null)) for update;if not found or v_inv.stock_quantity-v_inv.reserved_stock<v_q then raise exception 'Insufficient stock for %',v_p.name;end if;update inventory set stock_quantity=stock_quantity-v_q,updated_at=now() where id=v_inv.id;v_sub=v_sub+v_price*v_q;insert into order_items(order_id,product_id,variant_id,quantity,unit_price,personalization) values(v_order_id,v_p.id,(nullif(v_item->>'variant_id',''))::bigint,v_q,v_price,v_item->'personalization');end loop;if v_sub>=10000 then v_ship=0;end if;update orders set subtotal=v_sub,shipping_cost=v_ship,total=v_sub+v_ship,updated_at=now() where id=v_order_id;insert into order_status_history(order_id,status,note) values(v_order_id,'new','Order created');return jsonb_build_object('id',v_order_id,'order_number',v_num,'total',v_sub+v_ship);end;$$;

do $$declare t text;begin foreach t in array array['products','product_variants','product_images','inventory','orders','order_items','personalizations','order_status_history','customer_addresses','carts','cart_items','uploaded_assets','store_settings','categories'] loop execute 'alter table '||t||' enable row level security';end loop;end$$;
create policy products_public_read on products for select using(status='active' or is_admin());create policy product_admin_write on products for all using(is_admin()) with check(is_admin());
create policy variants_public_read on product_variants for select using(true);create policy variants_admin_write on product_variants for all using(is_admin()) with check(is_admin());
create policy images_public_read on product_images for select using(true);create policy images_admin_write on product_images for all using(is_admin()) with check(is_admin());
create policy inventory_public_read on inventory for select using(true);create policy inventory_admin_write on inventory for all using(is_admin()) with check(is_admin());
create policy orders_owner_read on orders for select using(user_id=auth.uid() or is_admin());create policy orders_admin_write on orders for all using(is_admin()) with check(is_admin());
create policy order_items_owner_read on order_items for select using(exists(select 1 from orders o where o.id=order_id and(o.user_id=auth.uid() or is_admin())));create policy order_items_admin_write on order_items for all using(is_admin()) with check(is_admin());
create policy history_owner_read on order_status_history for select using(exists(select 1 from orders o where o.id=order_id and(o.user_id=auth.uid() or is_admin())));create policy history_admin_write on order_status_history for all using(is_admin()) with check(is_admin());
create policy profile_owner on user_profiles for select using(id=auth.uid() or is_admin());create policy profile_update on user_profiles for update using(id=auth.uid() or is_admin()) with check(id=auth.uid() or is_admin());
create policy addresses_owner on customer_addresses for all using(user_id=auth.uid() or is_admin()) with check(user_id=auth.uid() or is_admin());
create policy carts_owner on carts for all using(user_id=auth.uid() or user_id is null) with check(user_id=auth.uid() or user_id is null);create policy cart_items_owner on cart_items for all using(exists(select 1 from carts c where c.id=cart_id and(c.user_id=auth.uid() or c.user_id is null))) with check(exists(select 1 from carts c where c.id=cart_id and(c.user_id=auth.uid() or c.user_id is null)));
create policy personalizations_owner on personalizations for select using(customer_id=auth.uid() or is_admin());create policy personalizations_admin on personalizations for all using(is_admin()) with check(is_admin());
create policy assets_owner on uploaded_assets for select using(user_id=auth.uid() or is_admin());create policy assets_insert on uploaded_assets for insert with check(user_id=auth.uid() or user_id is null);
insert into storage.buckets(id,name,public) values('artwork','artwork',false) on conflict(id) do nothing;
